using System;using System.IO;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Windows.Forms;
namespace ScoreModern {
 public static class NativeFontInitialization {
  public sealed class Data {public string Path,Program;public readonly Dictionary<int,string> Encoding=new Dictionary<int,string>();}
  public static bool External;static readonly Dictionary<string,Data> cache=new Dictionary<string,Data>();
  static string Settings{get{return "fontinit";}}
  public static void Load(){try{External=NativeSettings.Exists(Settings)&&NativeSettings.ReadAllText(Settings).Trim()=="external";}catch(IOException){}catch(UnauthorizedAccessException){}}
  public static void Set(bool external,bool save){External=external;cache.Clear();NativeTupletFonts.ClearResolvedFonts();if(save)NativeSettings.WriteAllText(Settings,external?"external":"internal");}
  static string Tokens(string text){return String.Join(" ",Regex.Split(Regex.Replace(text,@"([{}\[\]/])"," $1 "),@"\s+")).Trim();}
  static string Procedure(string text,string name,out string remainder){var m=Regex.Match(text,@"/"+name+@"\s*\{");if(!m.Success)throw new NotSupportedException("FONTINIT.PSC lacks /"+name);int start=m.Index+m.Length,depth=1,p=start;for(;p<text.Length&&depth>0;p++){if(text[p]=='{')depth++;if(text[p]=='}')depth--;}if(depth!=0)throw new InvalidDataException("Unclosed FONTINIT.PSC procedure");string body=text.Substring(start,p-start-1);var end=Regex.Match(text.Substring(p),@"^\s*(?:bind\s+)?def\b");if(!end.Success)throw new InvalidDataException("FONTINIT.PSC procedure terminator");remainder=text.Remove(m.Index,p+end.Length-m.Index);return Tokens(body);}
  public static Data Read(string root){if(String.IsNullOrEmpty(root))throw new InvalidOperationException("External FONTINIT.PSC needs the selected SCORE library.");string path=NativeSettings.Read("fontinit-path");if(String.IsNullOrWhiteSpace(path))path=NativeLibraryLocation.FileFor(root,"FONTINIT.PSC");var info=new FileInfo(path);if(!info.Exists)throw new FileNotFoundException("Selected external FONTINIT.PSC was not found; internal definitions were not substituted.",path);string key=info.FullName+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks;Data result;if(cache.TryGetValue(key,out result))return result;string program=File.ReadAllText(path,Encoding.GetEncoding(28591));result=Parse(program);result.Path=path;result.Program=program;cache.Clear();cache[key]=result;return result;}
  public static Data Parse(string program){string text=Regex.Replace(program,@"%[^\r\n]*","");string rest;string copy=Procedure(text,"CopyFont",out rest);if(copy!=Tokens("dup maxlength 3 -1 roll add dict begin {1 index /FID eq 2 index /UniqueID eq or {pop pop} {def} ifelse} forall /PaintType 2 def currentdict end"))throw new NotSupportedException("External CopyFont procedure is outside the supported native operations.");string re=Procedure(rest,"ReE",out rest);if(re!=Tokens("rncsmdict begin /newcdnm exch def /nfnm exch def /bfn exch def /bfdict bfn findfont def /nfn bfdict maxlength dict def bfdict {exch dup /FID ne {dup /Encoding eq {exch dup length array copy nfn 3 1 roll put} {exch nfn 3 1 roll put} ifelse} {pop pop} ifelse} forall nfn /FontName nfnm put newcdnm aload pop newcdnm length 2 idiv {nfn /Encoding get 3 1 roll put} repeat nfnm nfn definefont pop end"))throw new NotSupportedException("External ReE procedure is outside the supported native operations.");rest=Regex.Replace(rest,@"/rncsmdict\s+12\s+dict\s+def\b","");var array=Regex.Match(rest,@"/acc\s*\[([^\]]*)\]\s*def\b");if(!array.Success)throw new InvalidDataException("FONTINIT.PSC lacks its acc encoding array");var data=new Data{Program=program};string body=array.Groups[1].Value;var entries=Regex.Matches(body,@"(?<code>(?:[0-9]+#)?[0-9A-Za-z]+)\s*/(?<name>[A-Za-z][A-Za-z0-9_.-]*)");int position=0;foreach(Match entry in entries){if(!String.IsNullOrWhiteSpace(body.Substring(position,entry.Index-position)))throw new NotSupportedException("Unsupported FONTINIT.PSC encoding expression");string number=entry.Groups["code"].Value;int hash=number.IndexOf('#'),code=hash<0?Int32.Parse(number):Convert.ToInt32(number.Substring(hash+1),Int32.Parse(number.Substring(0,hash)));if(code<0||code>255)throw new InvalidDataException("FONTINIT.PSC encoding index must be 0..255");data.Encoding[code]=entry.Groups["name"].Value;position=entry.Index+entry.Length;}if(entries.Count==0||!String.IsNullOrWhiteSpace(body.Substring(position)))throw new NotSupportedException("Unsupported FONTINIT.PSC encoding contents");rest=rest.Remove(array.Index,array.Length);if(!String.IsNullOrWhiteSpace(rest))throw new NotSupportedException("Additional FONTINIT.PSC definitions are not supported; internal definitions were not substituted.");return data;}
  public static string Glyph(string root,int code,string otherwise){if(!External)return otherwise;string name;return Read(root).Encoding.TryGetValue(code,out name)?name:otherwise;}
  internal static string Prolog(string root,string otherwise){return External?Read(root).Program+"\n/SMCopyFont /CopyFont load def\n":otherwise;}
  public static void AddMenu(ContextMenuStrip menu,Func<string> root,Action changed){var item=new ToolStripMenuItem("Font initialisation: external FONTINIT.PSC");item.Click+=(s,e)=>{try{bool next=!External;if(next)Read(root());Set(next,true);changed();}catch(Exception error){MessageBox.Show(error.Message,"Font initialisation",MessageBoxButtons.OK,MessageBoxIcon.Error);}};menu.Items.Add(item);menu.Opening+=(s,e)=>{item.Checked=External;item.ToolTipText=External?NativeLibraryLocation.FileFor(root(),"FONTINIT.PSC"):"Internal font initialisation";};}
 }
}
